package org.stellarproximology.trident;
import android.app.*;import android.content.*;import android.graphics.PixelFormat;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public final class OverlayService extends Service{WindowManager wm;ImageButton b;WindowManager.LayoutParams p;public void onCreate(){super.onCreate();if(!Settings.canDrawOverlays(this)){stopSelf();return;}wm=(WindowManager)getSystemService(WINDOW_SERVICE);b=new ImageButton(this);b.setImageResource(R.drawable.trident_planet);b.setBackgroundColor(0);b.setContentDescription("Open Trident");p=new WindowManager.LayoutParams(dp(70),dp(70),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.START;p.x=getResources().getDisplayMetrics().widthPixels-dp(85);p.y=dp(220);final float[]t=new float[4];b.setOnTouchListener((v,e)->{if(e.getAction()==0){t[0]=e.getRawX();t[1]=e.getRawY();t[2]=p.x;t[3]=p.y;return true;}if(e.getAction()==2){p.x=(int)(t[2]+e.getRawX()-t[0]);p.y=(int)(t[3]+e.getRawY()-t[1]);wm.updateViewLayout(b,p);return true;}if(e.getAction()==1){if(Math.abs(e.getRawX()-t[0])<dp(8)&&Math.abs(e.getRawY()-t[1])<dp(8)){Intent i=new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);}return true;}return false;});wm.addView(b,p);}int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public void onDestroy(){try{wm.removeView(b);}catch(Exception ignored){}super.onDestroy();}public IBinder onBind(Intent i){return null;}}
